import{_ as a,o,c as r,ag as t}from"./chunks/framework.B_zcDAFh.js";const g=JSON.parse('{"title":"Boing Reactor","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-reactor.md","filePath":"guide/boing-reactor.md"}'),s={name:"guide/boing-reactor.md"};function i(n,e,c,d,h,l){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="boing-reactor" tabindex="-1">Boing Reactor <a class="header-anchor" href="#boing-reactor" aria-label="Permalink to &quot;Boing Reactor&quot;">​</a></h1><p><strong>Boing Reactor</strong> is a <a href="./boing-behavior.html">Boing Behavior</a> that <em>also</em> reacts to nearby <a href="./boing-effector.html">Boing Effectors</a>. The object still springs toward whatever target transform you set, and on top of that gets pushed and rotated by effectors moving through the scene.</p><p>All Boing Behavior inspector options (update mode, axis locks, params, shared params) apply here too.</p><h2 id="when-to-use-a-reactor-vs-a-reactor-field" tabindex="-1">When to Use a Reactor vs a Reactor Field <a class="header-anchor" href="#when-to-use-a-reactor-vs-a-reactor-field" aria-label="Permalink to &quot;When to Use a Reactor vs a Reactor Field&quot;">​</a></h2><p>A reactor processes each object individually. For a handful of distinct props — a row of bushes, a chest of collectibles — per-object reactors are simplest.</p><p>When many objects need to react to the same disturbance across a large area, use a <a href="./boing-reactor-field.html">Boing Reactor Field</a> instead. The field is sampled cheaply by samplers or directly in shaders, and avoids paying per-object reactor cost across a crowd.</p><p>See the <a href="/boing-kit/api/boing-reactor.html">API reference</a> for properties.</p>',7)])])}const f=a(s,[["render",i]]);export{g as __pageData,f as default};
